command:
$ready = Get-Content -LiteralPath 'evidence/workflow-005-session/fast-ready.json' -Raw | ConvertFrom-Json
$serverProcess = Get-Process -Id $ready.pid -ErrorAction Stop
if ($serverProcess.ProcessName -ne 'ovms') { throw 'Ready PID is no longer the expected OVMS process.' }
Stop-Process -InputObject $serverProcess -ErrorAction Stop
Wait-Process -Id $ready.pid -Timeout 15 -ErrorAction SilentlyContinue
foreach ($channel in @('stdout','stderr')) {
    $logProperty = $channel + '_log'
    $destination = 'evidence/workflow-005-session/fast-server.' + $channel + '.log'
    if (Test-Path -LiteralPath $destination) { throw 'Archive destination already exists.' }
    Copy-Item -LiteralPath $ready.$logProperty -Destination $destination -ErrorAction Stop
}
Write-Output ('Stopped only the fast OVMS process ' + $ready.pid)

